import { NextResponse } from 'next/server';

const API_URL = process.env.API_URL ?? 'http://localhost:4000';

/** /feeds/google/US.xml: Google Merchant Center feed, generated by the API from the live sellable catalogue. */
export async function GET(_req: Request, { params }: { params: Promise<{ country: string }> }) {
  const { country } = await params;
  const c = country.replace(/\.xml$/i, '').toUpperCase();
  if (!/^[A-Z]{2}$/.test(c)) return new NextResponse('Not found', { status: 404 });
  const res = await fetch(`${API_URL}/api/v1/feeds/google/${c}`, { headers: { 'x-requested-with': 'orvia' }, next: { revalidate: 900 } }).catch(() => null);
  if (!res || !res.ok) return new NextResponse('Feed unavailable', { status: res?.status === 404 ? 404 : 503 });
  return new NextResponse(await res.text(), { headers: { 'content-type': 'application/xml; charset=utf-8', 'cache-control': 'public, max-age=900' } });
}
